export class RetryCache {
  readonly #entries = new Map<string, Promise<unknown>>();

  getOrLoad<T>(key: string, loader: () => Promise<T>): Promise<T> {
    const existing = this.#entries.get(key) as Promise<T> | undefined;
    if (existing) return existing;

    const pending = loader();
    this.#entries.set(key, pending);

    pending.catch(() => {
      // A rejected load is removed so a later call can retry. Only delete the
      // entry if it still refers to this promise; an older rejection must not
      // delete a newer entry that replaced it.
      if (this.#entries.get(key) === pending) {
        this.#entries.delete(key);
      }
    });

    return pending;
  }
}
